def to_ascii_string(ascii_codes):
    """Return a string from the list of ASCII codes."""
    return ''.join(chr(code) for code in ascii_codes)

def to_ascii_list(text):
    """Return a list of ASCII codes for each character in text."""
    return [ord(char) for char in text]

def to_ascii_dict(text):
    """Return a dictionary with characters as keys and their ASCII codes as values."""
    return {char: ord(char) for char in text}

